document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("baseboard-form"),t=document.getElementById("baseboard-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const n=parseFloat(document.getElementById("baseboard-length").value),o=parseFloat(document.getElementById("baseboard-width").value),s=parseFloat(document.getElementById("baseboard-doors").value)||0;if(n<=0||o<=0)return t.textContent="Please enter room length and width.",void 0;const a=2*(n+o);let i=a-s;i<0&&(i=0);const r=1.1*i,d=Math.ceil(r/8),p=Math.ceil(r/12),c=Math.ceil(r/16);t.innerHTML=`\n        <div class="result-section">\n          <h4>Baseboard Length Needed:</h4>\n          <p><strong>${i.toFixed(1)} linear feet</strong> (exact)</p>\n          <p><strong>${r.toFixed(1)} linear feet</strong> (with 10% waste)</p>\n          <p>Room perimeter: ${a.toFixed(1)} ft</p>\n          ${s>0?`<p>Minus door openings: ${s} ft</p>`:""}\n        </div>\n        <div class="result-pieces">\n          <h4>Material Purchasing Options:</h4>\n          <p><strong>8-foot pieces:</strong> ${d} pieces (${8*d} total ft)</p>\n          <p><strong>12-foot pieces:</strong> ${p} pieces (${12*p} total ft)</p>\n          <p><strong>16-foot pieces:</strong> ${c} pieces (${16*c} total ft)</p>\n        </div>\n        <div class="result-tips">\n          <p><em>🔨 Plan cuts to minimize waste and joints</em></p>\n          <p><em>📐 Use longer pieces to reduce visible seams</em></p>\n          <p><em>✂️ Account for 45° miter cuts at corners</em></p>\n        </div>\n      `})});